import json
from src.nodes.base import BaseNode
from src.runtime.reality import get_geometry_inspector

_EMPTY = {"observed_scene_json": "{}", "reconciled_scene_json": "{}",
          "ok": False, "asset_count": 0, "exec_out": True}

class Hou_Mcp_Geometry_Truth(BaseNode):
    name = "hou_mcp_geometry_truth"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("root_path", "string", widget_type="text", default="/obj")
        self.add_input("scene_layout_json", "string", widget_type="text", default="")
        self.add_output("observed_scene_json")
        self.add_output("reconciled_scene_json")
        self.add_output("ok", "bool")
        self.add_output("asset_count", "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        root = (inputs.get("root_path") or "/obj").strip() or "/obj"
        try:
            inspector = get_geometry_inspector()
            observed = inspector.inspect(root)
            for err in observed.errors:
                self.log_error(err)
            observed_dict = observed.to_dict()
            reconciled = {}
            raw = (inputs.get("scene_layout_json") or "").strip()
            if raw:
                try:
                    planned = json.loads(raw)
                    reconciled = inspector.reconcile(observed_dict, planned)
                except Exception:
                    self.log_error("scene_layout_json is not valid JSON — skipping reconcile.")
            return {
                "observed_scene_json": json.dumps(observed_dict, sort_keys=True, indent=2),
                "reconciled_scene_json": json.dumps(reconciled, sort_keys=True, indent=2),
                "ok": observed.ok,
                "asset_count": len(observed.assets),
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Geometry truth inspection failed: {exc}")
            return dict(_EMPTY)

def register_node():
    return Hou_Mcp_Geometry_Truth
